### 2. replit_main.py
Ez a fő backend fájl a Repliten. Győződj meg róla, hogy a `Secrets` fülön beállítottad a következőket: `MODAL_TOKEN_ID`, `MODAL_TOKEN_SECRET`, `SUPERMEMORY_API_KEY`. Telepítsd a csomagokat: `flask`, `requests`, `supermemory`, `modal`.

```python
import os
import requests
from flask import Flask, render_template, request, jsonify
from supermemory import Supermemory

app = Flask(__name__, static_folder='static', template_folder='templates')

SUPERMEMORY_API_KEY = os.environ.get("SUPERMEMORY_API_KEY")
MODAL_URL = os.environ.get("MODAL_URL") 

memory_client = Supermemory(api_key=SUPERMEMORY_API_KEY)

@app.route('/')
def home():
    return render_template('index.html')

@app.route('/chat', methods=['POST'])
def chat():
    data = request.json
    user_message = data.get('message')
    history = data.get('history', [])

    search_response = memory_client.search.execute(
        query=user_message,
        top_k=10
    )

    context_text = ""
    if search_response and hasattr(search_response, 'results'):
        context_text = "\n\nRelevant Context from Memory:\n"
        for res in search_response.results:
            context_text += f"- {res.content}\n"

    system_prompt = {
        "role": "system", 
        "content": f"You are GLM-4.6. Answer the user comprehensively.{context_text}"
    }

    messages = [system_prompt] + history + [{"role": "user", "content": user_message}]

    payload = {
        "model": "bullpoint/GLM-4.6-AWQ",
        "messages": messages,
        "temperature": 1.0,
        "top_k": 1,
        "max_tokens": 8192,
        "stream": False
    }

    try:
        response = requests.post(
            f"{MODAL_URL}/v1/chat/completions", 
            json=payload,
            headers={"Content-Type": "application/json"},
            timeout=300
        )
        response.raise_for_status()
        ai_message = response.json()['choices'][0]['message']['content']

        memory_client.memories.add(
            content=f"User: {user_message}\nAI: {ai_message}",
            metadata={"source": "chat_log"}
        )

        return jsonify({"reply": ai_message})

    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
```

