## main.py

```python
import os
import modal
from flask import Flask, render_template, request, jsonify
from supermemory import Supermemory

app = Flask(__name__, static_folder="static", template_folder="templates")

SUPERMEMORY_API_KEY = os.environ.get("SUPERMEMORY_API_KEY")
MODAL_TOKEN_ID = os.environ.get("MODAL_TOKEN_ID")
MODAL_TOKEN_SECRET = os.environ.get("MODAL_TOKEN_SECRET")

memory_client = Supermemory(api_key=SUPERMEMORY_API_KEY)

generate_fn = modal.Function.from_name("glm-inference-app", "generate")

@app.route("/")
def home():
    return render_template("index.html")

@app.route("/chat", methods=["POST"])
def chat():
    data = request.json
    user_message = data.get("message")
    history = data.get("history", [])

    try:
        search_response = memory_client.search.execute(
            q=user_message,
            top_k=20,
        )

        context_text = ""
        if search_response and hasattr(search_response, "results") and search_response.results:
            context_text = "\n\nContext from memory:\n"
            for res in search_response.results[:10]:
                if hasattr(res, "content"):
                    context_text += f"- {res.content}\n"

        system_message = {
            "role": "system",
            "content": f"You are a highly capable AI assistant.{context_text}",
        }

        messages = [system_message] + history + [{"role": "user", "content": user_message}]

        ai_response = generate_fn.remote(
            messages=messages,
            temperature=1.0,
            top_k=1,
            max_tokens=16384,
        )

        memory_client.memories.add(
            content=f"User: {user_message}\nAI: {ai_response}",
            metadata={"timestamp": str(data.get("timestamp", ""))},
        )

        return jsonify({"reply": ai_response})

    except Exception as e:
        return jsonify({"error": str(e)}), 500

if __name__ == "__main__":
    app.run(host="0.0.0.0", port=8080)
