```javascript
const messagesWrapper = document.getElementById("messagesWrapper");
const messageInput = document.getElementById("messageInput");
const sendButton = document.getElementById("sendButton");
const themeToggle = document.getElementById("themeToggle");
const newChat = document.getElementById("newChat");

let conversationHistory = [];
let isProcessing = false;

const currentTheme = localStorage.getItem("theme") || "dark";
document.body.setAttribute("data-theme", currentTheme);

themeToggle.addEventListener("click", () => {
    const theme = document.body.getAttribute("data-theme");
    const newTheme = theme === "dark" ? "light" : "dark";
    document.body.setAttribute("data-theme", newTheme);
    localStorage.setItem("theme", newTheme);
});

newChat.addEventListener("click", () => {
    conversationHistory = [];
    messagesWrapper.innerHTML = '<div class="welcome-message"><div class="welcome-icon"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2"><path d="M21 15a2 2 0 0 1-2 2H7l-4 4V5a2 2 0 0 1 2-2h14a2 2 0 0 1 2 2z"/></svg></div></div>';
});

messageInput.addEventListener("input", () => {
    messageInput.style.height = "auto";
    messageInput.style.height = messageInput.scrollHeight + "px";
    sendButton.disabled = !messageInput.value.trim() || isProcessing;
});

messageInput.addEventListener("keydown", (e) => {
    if (e.key === "Enter" && !e.shiftKey) {
        e.preventDefault();
        if (!sendButton.disabled) {
            sendMessage();
        }
    }
});

sendButton.addEventListener("click", sendMessage);

async function sendMessage() {
    const text = messageInput.value.trim();
    if (!text || isProcessing) return;

    isProcessing = true;
    sendButton.disabled = true;

    const welcome = messagesWrapper.querySelector(".welcome-message");
    if (welcome) welcome.remove();

    addMessageToUI("user", text);

    messageInput.value = "";
    messageInput.style.height = "auto";

    const typingId = showTypingIndicator();

    try {
        const response = await fetch("/chat", {
            method: "POST",
            headers: {
                "Content-Type": "application/json",
            },
            body: JSON.stringify({
                message: text,
                history: conversationHistory,
                timestamp: Date.now(),
            }),
        });

        const data = await response.json();

        removeTypingIndicator(typingId);

        if (data.reply) {
            addMessageToUI("ai", data.reply);
            conversationHistory.push({ role: "user", content: text });
            conversationHistory.push({ role: "assistant", content: data.reply });
        } else {
            addMessageToUI("ai", "Hiba történt: " + (data.error || "Ismeretlen hiba"));
        }
    } catch (error) {
        removeTypingIndicator(typingId);
        addMessageToUI("ai", "Kapcsolódási hiba történt.");
    } finally {
        isProcessing = false;
        sendButton.disabled = false;
    }
}

function addMessageToUI(role, content) {
    const messageDiv = document.createElement("div");
    messageDiv.className = `chat-message ${role}`;

    const bubbleDiv = document.createElement("div");
    bubbleDiv.className = "message-bubble";
    bubbleDiv.textContent = content;

    messageDiv.appendChild(bubbleDiv);
    messagesWrapper.appendChild(messageDiv);

    messagesWrapper.scrollTop = messagesWrapper.scrollHeight;
}

function showTypingIndicator() {
    const id = "typing-" + Date.now();
    const messageDiv = document.createElement("div");
    messageDiv.className = "chat-message ai";
    messageDiv.id = id;

    const bubbleDiv = document.createElement("div");
    bubbleDiv.className = "message-bubble";

    const typingDiv = document.createElement("div");
    typingDiv.className = "typing-indicator";
    typingDiv.innerHTML = '<div class="typing-dot"></div><div class="typing-dot"></div><div class="typing-dot"></div>';

    bubbleDiv.appendChild(typingDiv);
    messageDiv.appendChild(bubbleDiv);
    messagesWrapper.appendChild(messageDiv);

    messagesWrapper.scrollTop = messagesWrapper.scrollHeight;

    return id;
}

function removeTypingIndicator(id) {
    const element = document.getElementById(id);
    if (element) element.remove();
}

if ("serviceWorker" in navigator) {
    navigator.serviceWorker.register("/static/sw.js");
}
