# main.py
import os
import time
import uuid
import requests
import supermemory
from flask import Flask, jsonify, render_template, request
from supermemory import Supermemory

app = Flask(__name__, static_folder="static", template_folder="templates")

MODAL_VLLM_BASE_URL = os.environ["MODAL_VLLM_BASE_URL"].rstrip("/")
SERVED_MODEL_NAME = os.environ.get("SERVED_MODEL_NAME", "chat")
SUPERMEMORY_API_KEY = os.environ["SUPERMEMORY_API_KEY"]

SUPERMEMORY_TIMEOUT = float(os.environ.get("SUPERMEMORY_TIMEOUT", "120.0"))
SUPERMEMORY_MAX_RETRIES = int(os.environ.get("SUPERMEMORY_MAX_RETRIES", "10"))
SUPERMEMORY_SEARCH_TOP_K = int(os.environ.get("SUPERMEMORY_SEARCH_TOP_K", "50"))
SUPERMEMORY_CONTEXT_ITEMS = int(os.environ.get("SUPERMEMORY_CONTEXT_ITEMS", "20"))

VLLM_TIMEOUT = float(os.environ.get("VLLM_TIMEOUT", "600.0"))
VLLM_MAX_TOKENS = int(os.environ.get("VLLM_MAX_TOKENS", "16384"))

client = Supermemory(
    api_key=SUPERMEMORY_API_KEY,
    timeout=SUPERMEMORY_TIMEOUT,
    max_retries=SUPERMEMORY_MAX_RETRIES,
)

def _safe_str(x):
    if x is None:
        return ""
    if isinstance(x, str):
        return x
    try:
        return str(x)
    except Exception:
        return ""

def _extract_search_context(query: str) -> str:
    resp = client.search.execute(q=query, top_k=SUPERMEMORY_SEARCH_TOP_K)
    results = getattr(resp, "results", None)
    if not results:
        return ""
    chunks = []
    for r in results[:SUPERMEMORY_CONTEXT_ITEMS]:
        content = _safe_str(getattr(r, "content", ""))
        if content.strip():
            chunks.append(content.strip())
    if not chunks:
        return ""
    return "\n\n".join(chunks)

def _normalize_history(history):
    if not isinstance(history, list):
        return []
    out = []
    for m in history:
        if not isinstance(m, dict):
            continue
        role = _safe_str(m.get("role")).strip()
        content = _safe_str(m.get("content"))
        if role in ("user", "assistant", "system") and content.strip():
            out.append({"role": role, "content": content})
    return out

def _call_vllm(messages):
    url = f"{MODAL_VLLM_BASE_URL}/v1/chat/completions"
    payload = {
        "model": SERVED_MODEL_NAME,
        "messages": messages,
        "temperature": 1.0,
        "top_p": 1.0,
        "stream": False,
        "max_tokens": VLLM_MAX_TOKENS,
        "extra_body": {"top_k": 1},
    }
    r = requests.post(url, json=payload, timeout=VLLM_TIMEOUT)
    r.raise_for_status()
    data = r.json()
    choices = data.get("choices") or []
    if not choices:
        raise RuntimeError("No choices returned")
    msg = (choices[0].get("message") or {}).get("content")
    if not isinstance(msg, str):
        raise RuntimeError("Invalid response format")
    return msg

def _store_memory(conversation_id: str, user_text: str, assistant_text: str):
    content = f"{user_text}\n\n{assistant_text}"
    client.memories.add(
        content=content,
        metadata={
            "conversation_id": conversation_id,
            "ts_ms": int(time.time() * 1000),
            "type": "chat_turn",
        },
    )

@app.get("/")
def index():
    return render_template("index.html")

@app.post("/api/chat")
def api_chat():
    payload = request.get_json(silent=True) or {}
    user_text = _safe_str(payload.get("message")).strip()
    history = _normalize_history(payload.get("history"))
    conversation_id = _safe_str(payload.get("conversation_id")).strip() or str(uuid.uuid4())
    if not user_text:
        return jsonify({"error": "Empty message"}), 400

    try:
        ctx = _extract_search_context(user_text)
        system_content = "You are a helpful assistant."
        if ctx:
            system_content = system_content + "\n\nAdditional context:\n" + ctx
        messages = [{"role": "system", "content": system_content}] + history + [{"role": "user", "content": user_text}]
        assistant_text = _call_vllm(messages)
        _store_memory(conversation_id, user_text, assistant_text)
        return jsonify({"reply": assistant_text, "conversation_id": conversation_id})
    except supermemory.APIError as e:
        return jsonify({"error": _safe_str(e)}), 502
    except requests.RequestException as e:
        return jsonify({"error": _safe_str(e)}), 502
    except Exception as e:
        return jsonify({"error": _safe_str(e)}), 500

@app.get("/health")
def health():
    return jsonify({"ok": True})
