import os
import modal

MODEL_ID = os.environ.get("MODEL_ID", "zai-org/GLM-4.6")
MAX_MODEL_LEN = int(os.environ.get("MAX_MODEL_LEN", "200000"))
GPU_SPEC = os.environ.get("GPU_SPEC", "B200:8")
GPU_MEMORY_UTILIZATION = float(os.environ.get("GPU_MEMORY_UTILIZATION", "0.98"))
TENSOR_PARALLEL_SIZE = int(os.environ.get("TENSOR_PARALLEL_SIZE", "8"))
MAX_NUM_SEQS = int(os.environ.get("MAX_NUM_SEQS", "64"))
DTYPE = os.environ.get("DTYPE", "auto")
QUANTIZATION = os.environ.get("QUANTIZATION", "awq")
ENABLE_PREFIX_CACHING = os.environ.get("ENABLE_PREFIX_CACHING", "1") == "1"

hf_cache = modal.Volume.from_name("hf-cache", create_if_missing=True)
vllm_cache = modal.Volume.from_name("vllm-cache", create_if_missing=True)

image = (
    modal.Image.from_registry("nvidia/cuda:12.8.0-devel-ubuntu22.04", add_python="3.12")
    .entrypoint([])
    .apt_install("git", "curl", "ca-certificates")
    .pip_install(
        "vllm==0.11.2",
        "transformers==4.49.0",
        "accelerate==1.1.1",
        "huggingface-hub==0.36.0",
        "hf-transfer==0.1.9",
        "safetensors==0.5.2",
    )
    .env(
        {
            "HF_HUB_ENABLE_HF_TRANSFER": "1",
            "HF_HUB_DISABLE_TELEMETRY": "1",
            "TOKENIZERS_PARALLELISM": "false",
            "TRANSFORMERS_NO_ADVISORY_WARNINGS": "1",
        }
    )
)

app = modal.App("glm-46-engine")

@app.cls(
    image=image,
    gpu=GPU_SPEC,
    timeout=60 * 60 * 24,
    container_idle_timeout=60 * 10,
    volumes={
        "/root/.cache/huggingface": hf_cache,
        "/root/.cache/vllm": vllm_cache,
    },
)
class Engine:
    def __init__(self):
        self._ready = False
        self._tokenizer = None
        self._llm = None

    @modal.enter()
    def _load(self):
        from transformers import AutoTokenizer
        from vllm import LLM

        self._tokenizer = AutoTokenizer.from_pretrained(MODEL_ID, trust_remote_code=True)
        llm_kwargs = {
            "model": MODEL_ID,
            "tensor_parallel_size": TENSOR_PARALLEL_SIZE,
            "max_model_len": MAX_MODEL_LEN,
            "dtype": DTYPE,
            "gpu_memory_utilization": GPU_MEMORY_UTILIZATION,
            "trust_remote_code": True,
            "max_num_seqs": MAX_NUM_SEQS,
        }

        if QUANTIZATION:
            llm_kwargs["quantization"] = QUANTIZATION

        if ENABLE_PREFIX_CACHING:
            llm_kwargs["enable_prefix_caching"] = True

        self._llm = LLM(**llm_kwargs)
        self._ready = True

    @modal.method()
    def chat(self, messages, temperature, top_k, max_tokens):
        from vllm import SamplingParams

        if not self._ready:
            raise RuntimeError("Engine not ready")

        if not isinstance(messages, list):
            raise ValueError("messages must be a list")

        prompt = self._tokenizer.apply_chat_template(
            messages,
            tokenize=False,
            add_generation_prompt=True,
        )

        params = SamplingParams(
            temperature=float(temperature),
            top_k=int(top_k),
            top_p=1.0,
            max_tokens=int(max_tokens),
        )

        outputs = self._llm.generate([prompt], params)
        if not outputs or not outputs[0].outputs:
            raise RuntimeError("Empty generation output")

        text = outputs[0].outputs[0].text
        if not isinstance(text, str):
            raise RuntimeError("Invalid generation output type")

        return text
